import json
import secrets

def generate_random_strings(num_strings, prefix):
    random_dict = {}
    for i in range(1, num_strings + 1):
        key = f"{prefix}_{i}"
        value = ''.join(secrets.choice('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789') for _ in range(10))
        random_dict[key] = value
    return json.dumps(random_dict)

# Example usage:
print(generate_random_strings(5, 'str'))
